const src = $input.first().json;
const p = src.payload || {};
function esc(v){ return String(v ?? '').replace(/'/g, "''"); }
let query = '';
if (src.recurso === 'evento') {
  query = `insert into eventos_campanha (id, id_candidato, nome_evento, tipo_evento, descricao, data_evento, local_nome, endereco, cidade, uf, capacidade_estimada, link_confirmacao, status, origem_dados, metadata) values (coalesce(nullif('${esc(src.referencia_id)}','')::uuid, gen_random_uuid()), 'ricardo-vale', '${esc(p.nome_evento)}', '${esc(p.tipo_evento)}', '${esc(p.descricao)}', nullif('${esc(p.data_evento)}','')::timestamptz, '${esc(p.local_nome)}', '${esc(p.endereco)}', '${esc(p.cidade)}', '${esc(p.uf)}', ${Number(p.capacidade_estimada || 0)}, '${esc(p.link_confirmacao)}', '${esc(p.status || 'ativo')}', 'plataforma_admin', '${esc(JSON.stringify(p.metadata || {}))}'::jsonb) on conflict (id) do update set nome_evento = excluded.nome_evento, tipo_evento = excluded.tipo_evento, descricao = excluded.descricao, data_evento = excluded.data_evento, local_nome = excluded.local_nome, endereco = excluded.endereco, cidade = excluded.cidade, uf = excluded.uf, capacidade_estimada = excluded.capacidade_estimada, link_confirmacao = excluded.link_confirmacao, status = excluded.status, metadata = excluded.metadata, atualizado_em = now() returning id;`;
} else if (src.recurso === 'canal') {
  query = `insert into canais_integracao (id, id_candidato, nome_canal, tipo_canal, identificador_externo, url_canal, status, origem_dados, metadata) values (coalesce(nullif('${esc(src.referencia_id)}','')::uuid, gen_random_uuid()), 'ricardo-vale', '${esc(p.nome_canal)}', '${esc(p.tipo_canal)}', '${esc(p.identificador_externo)}', '${esc(p.url_canal)}', '${esc(p.status || 'ativo')}', 'plataforma_admin', '${esc(JSON.stringify(p.metadata || {}))}'::jsonb) on conflict (id) do update set nome_canal = excluded.nome_canal, tipo_canal = excluded.tipo_canal, identificador_externo = excluded.identificador_externo, url_canal = excluded.url_canal, status = excluded.status, metadata = excluded.metadata, atualizado_em = now() returning id;`;
} else {
  query = `insert into agendas_campanha (id, id_candidato, titulo, descricao, data_inicio, data_fim, local_nome, endereco, cidade, uf, canal_confirmacao, status, origem_dados, metadata) values (coalesce(nullif('${esc(src.referencia_id)}','')::uuid, gen_random_uuid()), 'ricardo-vale', '${esc(p.titulo)}', '${esc(p.descricao)}', nullif('${esc(p.data_inicio)}','')::timestamptz, nullif('${esc(p.data_fim)}','')::timestamptz, '${esc(p.local_nome)}', '${esc(p.endereco)}', '${esc(p.cidade)}', '${esc(p.uf)}', '${esc(p.canal_confirmacao)}', '${esc(p.status || 'planejado')}', 'plataforma_admin', '${esc(JSON.stringify(p.metadata || {}))}'::jsonb) on conflict (id) do update set titulo = excluded.titulo, descricao = excluded.descricao, data_inicio = excluded.data_inicio, data_fim = excluded.data_fim, local_nome = excluded.local_nome, endereco = excluded.endereco, cidade = excluded.cidade, uf = excluded.uf, canal_confirmacao = excluded.canal_confirmacao, status = excluded.status, metadata = excluded.metadata, atualizado_em = now() returning id;`;
}
return [{ json: { ...src, upsert_sql: query } }];

